"""No original source episode generated by these focused model tests."""
import pathlib,sys,unittest
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parent))
import numpy as np
from run_cs05_original_raw_visual_memory import (
    RankOneEncoder,PcaReward,RawEpisodic,PcaErased,seed,ROLE_COUNTS,REPS
)
def example():
    rng=np.random.default_rng(919)
    rows=[]
    base=np.zeros(147,dtype=np.uint8)
    for i in range(192):
        c=(i//2)%2;f=(i//4)%2;a=i%2
        cue=base.copy();fork=base.copy()
        cue[14]=5+c;fork[34]=5+f
        # Only synthetic unit-test labels; never represent original source.
        success=int((a==0)==(c==f))
        rows.append({"cue_image":cue.tolist(),"fork_image":fork.tolist(),
                     "chosen_lower":a,"terminal_success":success})
    return rows
class Boundaries(unittest.TestCase):
    def test_fit_pca_representation(self):
        rows=example()
        e=RankOneEncoder()
        e.fit([r["cue_image"] for r in rows])
        self.assertGreater(e.explained,.99)
        self.assertNotEqual(e.project(rows[0]["cue_image"]),
                            e.project(rows[2]["cue_image"]))
    def test_candidate_learns_raw_reward_without_label(self):
        m=PcaReward();m.fit(example())
        self.assertEqual(m.updates,192*80)
        self.assertNotEqual(m.choose(example()[0]["cue_image"],example()[0]["fork_image"]),
                            PcaErased(m).choose(example()[0]["cue_image"],example()[0]["fork_image"])
                            if False else 2) # action stays binary
    def test_controls_fit_exact_original_encoded_vectors(self):
        rows=example()
        r=RawEpisodic();f=RawEpisodic(frame_only=True)
        r.fit(rows);f.fit(rows)
        self.assertEqual(r.updates,192)
        self.assertIn(r.choose(rows[0]["cue_image"],rows[0]["fork_image"]),(0,1))
        self.assertEqual(len({r.key(x["cue_image"],x["fork_image"],x["chosen_lower"]) for x in rows}),8)
    def test_roles_disjoint(self):
        ids={seed(role,r,i) for role,n in ROLE_COUNTS.items() for r in REPS for i in range(n)}
        self.assertEqual(len(ids),3*(192+64+128))
        self.assertNotIn(940003,ids)
if __name__=="__main__":
    unittest.main()
